/* ============================================================================
 * MultiCurrencyTreasuryExtraModals.tsx — modals ported from the original page 3.11.html.
 * ----------------------------------------------------------------------------
 * AUTO-GENERATED by port_missing_modals.py — regenerate rather than hand-edit.
 *
 * These dialogs exist in the legacy HTML and were reachable there via
 * onclick="openModal('…')", but were never carried into the React port, so the
 * buttons that target them did nothing. Markup, titles, sizes, tables and
 * footer actions are ported from the source.
 *
 * Legacy bridges applied:
 *   openModal('x')        -> onOpen('x')
 *   data-bs-dismiss       -> onClose
 *   processAction(...)    -> doAction(...)  (spinner -> receipt)
 * ========================================================================== */
import type { ReactNode } from "react";
import { useEffect, useRef, useState } from "react";
import styles from "../styles/multi-currency-treasury.module.css";

const s = styles as Record<string, string>;
const cx = (...c: (string | false | undefined)[]) =>
	c.filter(Boolean).join(" ");

interface Props {
	active: string | null;
	onClose: () => void;
	onOpen: (id: string) => void;
}

interface Result {
	msg: string;
	ref?: string;
}

/* Modal shell — mirrors the shared kit used by the hand-written modals so
 * these dialogs look and behave identically. */
function MBox({
	id,
	active,
	title,
	size = "md",
	onClose,
	children,
	footer,
}: {
	id: string;
	active: string | null;
	title: ReactNode;
	size?: "md" | "lg" | "xl";
	onClose: () => void;
	children: ReactNode;
	footer?: ReactNode;
}) {
	if (active !== id) return null;
	return (
		<>
			<div className={s.backdrop} onClick={onClose} />
			<div className={s.modalWrap} role="dialog" aria-modal="true">
				<div
					className={cx(
						s.modalBox,
						size === "lg" && s.modalBoxLg,
						size === "xl" && s.modalBoxXl,
					)}
				>
					<div className={s.modalHeader}>
						<h5 className={s.modalTitle}>{title}</h5>
						<button
							type="button"
							className="btn-close"
							aria-label="Close"
							onClick={onClose}
						/>
					</div>
					<div className={s.modalBody}>{children}</div>
					{footer && <div className={s.modalFooter}>{footer}</div>}
				</div>
			</div>
		</>
	);
}

function Busy() {
	return (
		<div className={s.loadingOv}>
			<div className={s.spinner} />
			<p className={s.loadingLabel}>Processing...</p>
		</div>
	);
}

export default function MultiCurrencyTreasuryExtraModals({
	active,
	onClose,
	onOpen,
}: Props) {
	const [results, setResults] = useState<Record<string, Result>>({});
	const [busy, setBusy] = useState<string | null>(null);
	const [flows, setFlows] = useState<Record<string, number>>({});
	const timer = useRef<number | undefined>(undefined);

	/* LEGACY BRIDGE: cacheResettable() — clear state when the modal closes. */
	useEffect(() => {
		if (active === null) {
			setResults({});
			setBusy(null);
			setFlows({});
		}
	}, [active]);
	useEffect(() => () => window.clearTimeout(timer.current), []);

	/* LEGACY BRIDGE: processAction() — 1.2s spinner, then a receipt. */
	const doAction = (id: string, msg: string, ref?: string) => {
		setBusy(id);
		timer.current = window.setTimeout(() => {
			setResults((p) => ({ ...p, [id]: { msg, ref } }));
			setBusy(null);
		}, 1200);
	};

	const nextFlow = (key: string, total: number) => {
		const cur = flows[key] ?? 1;
		if (cur >= total) {
			onClose();
			return;
		}
		setFlows((p) => ({ ...p, [key]: cur + 1 }));
	};
	void nextFlow;

	const bodyFor = (id: string, content: ReactNode) => {
		if (busy === id) return <Busy />;
		const r = results[id];
		if (r)
			return (
				<div className={s.receipt}>
					<div className={s.receiptIcon}>
						<i className="bi bi-check-lg" />
					</div>
					<h5 style={{ fontWeight: 700, color: "var(--pm-accent)" }}>
						{r.msg}
					</h5>
					{r.ref && (
						<p style={{ fontSize: 12, color: "var(--pm-muted)" }}>
							Ref: {r.ref}
						</p>
					)}
				</div>
			);
		return content;
	};

	return (
		<>
			<MBox
				id="reconcileModal"
				active={active}
				size="lg"
				onClose={onClose}
				title={
					<>
						<i className="bi bi-list-check me-2" /> Reconciliation Center
					</>
				}
				footer={
					<>
						<button type="button" className={s.btnPm} onClick={onClose}>
							Close
						</button>
					</>
				}
			>
				{bodyFor(
					"reconcileModal",
					<>
						<div className={cx(s.pills, "mb-3")}>
							<button
								type="button"
								className={cx(s.pill, s.pillActive)}
								onClick={onClose}
							>
								Nostro
							</button>
							<button type="button" className={s.pill} onClick={onClose}>
								Forward
							</button>
							<button type="button" className={s.pill} onClick={onClose}>
								Exceptions
							</button>
						</div>
						<div id="rec-nostro" className={cx(s.tpanel, s.tpanelActive)}>
							<div className="table-responsive">
								<table className={s.tbl}>
									<thead>
										<tr>
											<th>Account</th>
											<th>Bank Balance</th>
											<th>Internal Ledger</th>
											<th>Difference</th>
											<th>Status</th>
										</tr>
									</thead>
									<tbody>
										<tr>
											<td>USD Nostro</td>
											<td>318,450</td>
											<td>318,450</td>
											<td>0</td>
											<td>
												<span className={cx(s.badge, s.badgeS)}>Matched</span>
											</td>
										</tr>
										<tr>
											<td>EUR Nostro</td>
											<td>142,800</td>
											<td>142,800</td>
											<td>0</td>
											<td>
												<span className={cx(s.badge, s.badgeS)}>Matched</span>
											</td>
										</tr>
										<tr>
											<td>GBP Nostro</td>
											<td>67,200</td>
											<td>66,850</td>
											<td>350</td>
											<td>
												<span className={cx(s.badge, s.badgeW)}>Exception</span>
											</td>
										</tr>
									</tbody>
								</table>
							</div>
						</div>
						<div id="rec-forward" className={s.tpanel}>
							<div className="table-responsive">
								<table className={s.tbl}>
									<thead>
										<tr>
											<th>Contract</th>
											<th>MTM (Bank)</th>
											<th>MTM (Ledger)</th>
											<th>Difference</th>
											<th>Status</th>
										</tr>
									</thead>
									<tbody>
										<tr>
											<td>FX-8821</td>
											<td>+KES 84K</td>
											<td>+KES 84K</td>
											<td>0</td>
											<td>
												<span className={cx(s.badge, s.badgeS)}>Matched</span>
											</td>
										</tr>
										<tr>
											<td>FX-8794</td>
											<td>+KES 42K</td>
											<td>+KES 42K</td>
											<td>0</td>
											<td>
												<span className={cx(s.badge, s.badgeS)}>Matched</span>
											</td>
										</tr>
									</tbody>
								</table>
							</div>
						</div>
						<div id="rec-exception" className={s.tpanel}>
							<div
								className="p-3 rounded mb-2"
								style={{ background: "var(--pm-warning-soft)" }}
							>
								<div className="d-flex justify-content-between">
									<div>
										<strong>GBP Nostro mismatch</strong>
										<div style={{ fontSize: 11, color: "#92400E" }}>
											KES 350 difference — SWIFT fee not booked
										</div>
									</div>
									<button
										type="button"
										className={cx(s.btnPm, s.btnSm)}
										onClick={onClose}
									>
										Resolve
									</button>
								</div>
							</div>
						</div>
					</>,
				)}
			</MBox>
			<MBox
				id="transferDetailModal"
				active={active}
				onClose={onClose}
				title={
					<>
						<i className="bi bi-file-earmark-text me-2" /> Transfer Details
					</>
				}
				footer={
					<>
						<button type="button" className={s.btnPm} onClick={onClose}>
							Close
						</button>
					</>
				}
			>
				{bodyFor(
					"transferDetailModal",
					<>
						<div
							className="p-3 rounded mb-3"
							style={{ background: "var(--pm-surface-2)", fontSize: 13 }}
						>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">Transfer ID</span>
								<strong>XFR-20250627-7712</strong>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">Status</span>
								<span className={cx(s.badge, s.badgeS)}>Completed</span>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">From</span>
								<strong>USD Account</strong>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">To</span>
								<strong>KES Account</strong>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">Amount</span>
								<strong>USD 50,000 → KES 6,471,000</strong>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">Rate</span>
								<strong>129.42</strong>
							</div>
							<div className="d-flex justify-content-between mb-2">
								<span className="text-muted">Fee</span>
								<strong>KES 12,942</strong>
							</div>
							<div className="d-flex justify-content-between">
								<span className="text-muted">Value Date</span>
								<strong>27 Jun 2025, 14:32 EAT</strong>
							</div>
						</div>
						<div className="d-flex gap-2">
							<button
								type="button"
								className={cx(s.btnPm, s.btnSm)}
								onClick={onClose}
							>
								<i className="bi bi-download"></i>Receipt PDF
							</button>
							<button
								type="button"
								className={cx(s.btnPm, s.btnSm)}
								onClick={onClose}
							>
								<i className="bi bi-share"></i>Share
							</button>
						</div>
					</>,
				)}
			</MBox>
		</>
	);
}
